  "clauses": [
    {
      "clause_type": "processing_instructions",
      "text": "Processor processes personal data only on the Controller's documented instructions, including for third-country transfers, unless required by Union/Member State law."
    },
    {
      "clause_type": "confidentiality",
      "text": "Persons authorised to process personal data must be bound by confidentiality commitments or statutory confidentiality obligations."
    },
    {
      "clause_type": "information_security",
      "text": "Processor implements appropriate technical and organisational measures appropriate to risk; a summary of measures is only 'available on request'."
    },
    {
      "clause_type": "subprocessors",
      "text": "Processor may appoint sub-processors at its own discretion, informs Controller only after changes take effect, and Controller waives its right to object."
    },
    {
      "clause_type": "data_subject_rights_assistance",
      "text": "Processor assists Controller in responding to data subject requests under Chapter III GDPR."
    },
    {
      "clause_type": "data_breach_notification",
      "text": "Processor must notify Controller of a personal data breach within fourteen (14) days of awareness."
    },
    {
      "clause_type": "dpia_assistance",
      "text": "Processor provides reasonable assistance with data protection impact assessments only 'where commercially agreed'."
    },
    {
      "clause_type": "data_retention_and_deletion",
      "text": "After termination, Processor may retain personal data indefinitely for its own purposes, including product improvement and model training."
