      "severity": "high"
    },
    {
      "clause_type": "audit_rights",
      "rationale": "Express exclusion of on-site inspections and Controller-mandated audits contradicts Article 28(3)(h) GDPR, which requires the Processor to allow for and contribute to audits, including inspections.",
      "severity": "high"
    },
    {
      "clause_type": "international_data_transfers",
      "rationale": "Transfers to third-country affiliates are permitted before any Chapter V transfer mechanism (e.g., SCCs, adequacy, derogation) is agreed; deferring the mechanism leaves transfers potentially unlawful.",
      "severity": "high"
    },
    {
      "clause_type": "information_security",
      "rationale": "No annex or specified list of technical and organisational measures is incorporated; measures are only summarised 'on request', which weakens enforceability and Article 32 evidence.",
      "severity": "medium"
    },
    {
      "clause_type": "dpia_assistance",
      "rationale": "Conditioning DPIA/prior-consultation assistance on separate commercial agreement undercuts the mandatory assistance duty in Article 28(3)(f) GDPR.",
      "severity": "medium"
    },
    {
      "clause_type": "processing_instructions",
